```javascript
const axios = require("axios");

async function getData(query) {
  try {
    const response = await axios.get(
      `https://api.ryukomik.web.id/kiryuu/search?q=${query}`
    );

    return response.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

getData("jujutsu")
  .then(result => m.reply(JSON.stringify(result, null, 2)))
  .catch(error => m.reply(error.message));
```
